/** The desktop shell's t3 command bridge. */
export interface DesktopCliCommandBridge {
  readonly getState: () => Promise<string>
}

export function getDesktopCliCommandBridge(): DesktopCliCommandBridge | undefined {
  return typeof window === "undefined" ? undefined : window.desktopBridge?.cliCommand
}

export function describeDesktopCliCommand(state: string): string {
  return `t3 command: ${state}`
}
